import AppKit

/// Polls the system pasteboard and records new copies into the history.
final class PasteboardMonitor {
    /// Markers password managers and other apps set on copies that shouldn't be saved.
    /// See http://nspasteboard.org
    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
    ]

    private let store: HistoryStore
    private var lastChangeCount: Int
    private var timer: Timer?

    init(store: HistoryStore) {
        self.store = store
        lastChangeCount = NSPasteboard.general.changeCount
    }

    func start() {
        // Capture whatever is on the clipboard at launch.
        capture(NSPasteboard.general)
        let timer = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.check() }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Call after the app itself writes to the pasteboard so it isn't re-recorded.
    func ignoreCurrentContents() {
        lastChangeCount = NSPasteboard.general.changeCount
    }

    private func check() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        capture(pasteboard)
    }

    private func capture(_ pasteboard: NSPasteboard) {
        let types = pasteboard.types ?? []
        if types.contains(where: { Self.skipTypes.contains($0.rawValue) }) { return }
        // Files copied in Finder are out of scope.
        if types.contains(.fileURL) { return }

        if let text = pasteboard.string(forType: .string),
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            store.addText(text, rtf: pasteboard.data(forType: .rtf))
            return
        }

        if let png = pasteboard.data(forType: .png) {
            store.addImage(png: png)
        } else if let tiff = pasteboard.data(forType: .tiff),
                  let rep = NSBitmapImageRep(data: tiff),
                  let png = rep.representation(using: .png, properties: [:]) {
            store.addImage(png: png)
        }
    }
}
